pub(crate) fn emit_a_handle(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; emit_a_handle_name(name, view) },
        _ => false,
    }
}

pub(crate) fn emit_a_handle_name(name: &str, view: bool) -> bool {
    if view { return false; }
    name == "Shared" || name == "SharedMut"
}

